@Suite @MainActor struct MobileSketchPNGTests {
    /// Real public PencilKit APIs, no PKCanvasView gesture synthesis or device/Pencil required.
    /// Freeze generated bytes once for cross-platform transports; do not assume archives or
    /// raster compression reproduce identical bytes on a different OS/SDK.
    static func fixtureDrawing(offset: CGFloat = 0) -> PKDrawing {
        let points = [CGPoint(x: 8 + offset, y: 12), CGPoint(x: 36 + offset, y: 42), CGPoint(x: 80 + offset, y: 24)]
            .enumerated().map { index, point in
                PKStrokePoint(location: point, timeOffset: Double(index) * 0.1,
                    size: CGSize(width: 4, height: 4), opacity: 1, force: 0.5, azimuth: 0, altitude: .pi / 2)
            }
        let path = PKStrokePath(controlPoints: points, creationDate: Date(timeIntervalSince1970: 1_700_000_000))
        return PKDrawing(strokes: [PKStroke(ink: PKInk(.pen, color: .blue), path: path, randomSeed: 42)])
    }
    private let rect = CGRect(x: 0, y: 0, width: 96, height: 64)
    private func regularPNG() throws -> Data {
        let format = UIGraphicsImageRendererFormat(); format.scale = 1
        let image = UIGraphicsImageRenderer(size: rect.size, format: format).image { context in
            UIColor.white.setFill(); context.fill(rect)
        }
        return try MobileSketchPNG.pngForNewSketch(from: #require(image.cgImage))
    }

    private func pixels(_ image: CGImage) throws -> Data {
        var bytes = Data(count: image.width * image.height * 4)
        try bytes.withUnsafeMutableBytes { raw in
            let context = try #require(CGContext(data: raw.baseAddress, width: image.width, height: image.height,
                bitsPerComponent: 8, bytesPerRow: image.width * 4, space: CGColorSpaceCreateDeviceRGB(),
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue | CGBitmapInfo.byteOrder32Big.rawValue))
            context.draw(image, in: CGRect(x: 0, y: 0, width: image.width, height: image.height))
        }
        return bytes
    }
    private func decodedImage(_ data: Data) throws -> CGImage {
        let source = try #require(CGImageSourceCreateWithData(data as CFData, nil))
        return try #require(CGImageSourceCreateImageAtIndex(source, 0, nil))
    }

    @Test func maximumEditorCanvasEdgeInkRoundTripsWithoutExpandingRaster() throws {
        let size = CGSize(width: MobileSketchSession.maximumDimension, height: 64)
        let points = [CGPoint(x: 0, y: 32), CGPoint(x: size.width, y: 32)].enumerated().map { index, point in
            PKStrokePoint(location: point, timeOffset: Double(index) * 0.1,
                size: CGSize(width: 12, height: 12), opacity: 1, force: 1, azimuth: 0, altitude: .pi / 2)
        }
        let drawing = PKDrawing(strokes: [PKStroke(ink: PKInk(.pen, color: .blue),
            path: PKStrokePath(controlPoints: points, creationDate: Date(timeIntervalSince1970: 0)))])
        #expect(drawing.bounds.minX < 0 || drawing.bounds.maxX > size.width)
        let session = try MobileSketchSession(drawing: drawing, canvasSize: size)
        defer { session.teardown() }
        let raster = try #require(drawing.image(from: CGRect(origin: .zero, size: size), scale: 1).cgImage)
        #expect(raster.width == 4096 && raster.height == 64)
        let png = try MobileSketchPNG.pngForNewSketch(from: raster)
        let embedded = try MobileSketchPNG.embed(drawing: drawing, in: png)
        let reopened = try #require(try MobileSketchPNG.drawing(in: embedded))
        #expect(reopened == drawing)
        #expect(try pixels(decodedImage(embedded)) == pixels(decodedImage(png)))
        let rerender = try #require(reopened.image(from: CGRect(origin: .zero, size: size), scale: 1).cgImage)
        #expect(try pixels(rerender) == pixels(raster))
        // The codec's independent geometry budget remains intact; no unlimited widening.
        let distant = drawing.transformed(using: CGAffineTransform(scaleX: 10, y: 1))
        #expect(throws: MobileSketchPNG.Failure.self) { try MobileSketchPNG.embed(drawing: distant, in: png) }
    }

    @Test func newSketchEncoderNormalizesOnlyOwnRasterToSRGBAndKeepsAlpha() throws {
        let format = UIGraphicsImageRendererFormat(); format.scale = 1; format.opaque = false
        let renderer = UIGraphicsImageRenderer(size: CGSize(width: 2, height: 2), format: format)
        let nativePNG = renderer.pngData { context in
            UIColor(displayP3Red: 0.8, green: 0.2, blue: 0.3, alpha: 0.5).setFill()
            context.fill(CGRect(x: 0, y: 0, width: 1, height: 2))
        }
        print("Native UIGraphicsImageRenderer PNG chunks: \(chunks(nativePNG).map { $0.type })")
        // Read back the EXACT old regularPNG renderer, rather than inferring its chunks from
        // an unsupportedMetadata error or from the distinct PencilKit PNG encoder.
        let legacyBaseline = UIGraphicsImageRenderer(size: rect.size, format: format).pngData { context in
            UIColor.white.setFill(); context.fill(rect)
        }
        print("Legacy regularPNG native chunks: \(chunks(legacyBaseline).map { $0.type })")
        #expect(try MobileSketchPNG.drawingData(in: legacyBaseline) == nil)
        #expect(try MobileSketchPNG.drawingData(in: nativePNG) == nil)
        let source = try decodedImage(nativePNG)
        let encoded = try MobileSketchPNG.pngForNewSketch(from: source)
        #expect(chunks(encoded).map { $0.type } == ["IHDR", "sRGB", "IDAT", "IEND"])
        #expect(chunks(encoded).first { $0.type == "sRGB" }?.data == Data([0]))
        let image = try decodedImage(encoded)
        #expect(image.width == source.width && image.height == source.height)
        // Independently establish the expected sRGB conversion before comparing output pixels.
        var expected = Data(count: source.width * source.height * 4)
        try expected.withUnsafeMutableBytes { bytes in
            let space = try #require(CGColorSpace(name: CGColorSpace.sRGB))
            let context = try #require(CGContext(data: bytes.baseAddress, width: source.width, height: source.height,
                bitsPerComponent: 8, bytesPerRow: source.width * 4, space: space,
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue | CGBitmapInfo.byteOrder32Big.rawValue))
            context.draw(source, in: CGRect(x: 0, y: 0, width: source.width, height: source.height))
        }
        var actual = Data(count: image.width * image.height * 4)
        try actual.withUnsafeMutableBytes { bytes in
            let space = try #require(CGColorSpace(name: CGColorSpace.sRGB))
            let context = try #require(CGContext(data: bytes.baseAddress, width: image.width, height: image.height,
                bitsPerComponent: 8, bytesPerRow: image.width * 4,
                space: space,
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue | CGBitmapInfo.byteOrder32Big.rawValue))
            context.draw(image, in: CGRect(x: 0, y: 0, width: image.width, height: image.height))
        }
        // PNG stores straight-alpha components, so premultiplication round trips can round RGB
        // by one 8-bit level. Alpha must remain exact, and transparent pixels stay transparent.
        #expect(zip(actual, expected).allSatisfy { pair in abs(Int(pair.0) - Int(pair.1)) <= 1 })
        #expect(stride(from: 3, to: actual.count, by: 4).allSatisfy { actual[$0] == expected[$0] })
        let alphas = stride(from: 3, to: actual.count, by: 4).map { actual[$0] }
        #expect(alphas.contains(0) && alphas.contains { $0 > 0 && $0 < 255 })
        let drawing = Self.fixtureDrawing()
        let sketch = try MobileSketchPNG.embed(drawing: drawing, in: encoded)
        #expect(try MobileSketchPNG.drawing(in: sketch) == drawing)
        #expect(try pixels(decodedImage(sketch)) == pixels(decodedImage(encoded)))
        // A genuinely compressed native PNG stays refused by embed; normalization is explicit.
        if chunks(nativePNG).contains(where: { ["iCCP", "zTXt"].contains($0.type) }) {
            #expect(throws: MobileSketchPNG.Failure.unsupportedMetadata) {
                try MobileSketchPNG.embed(drawing: drawing, in: nativePNG)
            }
        }
    }

    @Test func newSketchEncoderRejectsDimensionAndPixelLimitsBeforeRasterAllocation() throws {
        func grayImage(width: Int, height: Int, bits: Int) throws -> CGImage {
            let rowBytes = (width * bits + 7) / 8
            let data = Data(count: rowBytes * height)
            let provider = try #require(CGDataProvider(data: data as CFData))
            return try #require(CGImage(width: width, height: height, bitsPerComponent: bits,
                bitsPerPixel: bits, bytesPerRow: rowBytes, space: CGColorSpaceCreateDeviceGray(),
                bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.none.rawValue), provider: provider,
                decode: nil, shouldInterpolate: false, intent: .defaultIntent))
        }
        let tooWide = try grayImage(width: 8193, height: 1, bits: 8)
        #expect(throws: MobileSketchPNG.Failure.tooLarge) { try MobileSketchPNG.pngForNewSketch(from: tooWide) }
        // A 1-bit source uses only ~2MiB; the forbidden RGBA allocation must never occur.
        let tooManyPixels = try grayImage(width: 8192, height: 2049, bits: 1)
        #expect(throws: MobileSketchPNG.Failure.tooLarge) { try MobileSketchPNG.pngForNewSketch(from: tooManyPixels) }
    }

    @Test func actualDrawingRoundTripPreservesExactPayloadStrokesAndRaster() throws {
        let drawing = Self.fixtureDrawing()
        #expect(drawing.strokes.count == 1 && !drawing.bounds.isEmpty)
        let rendered = drawing.image(from: rect, scale: 1)
        let png = try #require(rendered.pngData()), original = drawing.dataRepresentation()
        let encoded = try MobileSketchPNG.embed(drawingData: original, in: png)
        #expect(try MobileSketchPNG.drawingData(in: encoded) == original)
        let reopened = try #require(try MobileSketchPNG.drawing(in: encoded))
        #expect(reopened == drawing)
        #expect(try pixels(decodedImage(encoded)) == pixels(decodedImage(png)))
        #expect(try pixels(#require(reopened.image(from: rect, scale: 1).cgImage)) == pixels(#require(rendered.cgImage)))
        #expect(chunks(encoded).filter { $0.type == "thND" }.count == 1)
    }

    @Test func frozenRealDrawingFixtureLoadsLosslesslyOnIOS() throws {
        let bundle = Bundle(for: MobileSketchPNGFixtureBundle.self)
        let pngURL = try #require(bundle.url(forResource: "one-stroke", withExtension: "png", subdirectory: "sketch"))
        let drawingURL = try #require(bundle.url(forResource: "one-stroke", withExtension: "drawing", subdirectory: "sketch"))
        let png = try Data(contentsOf: pngURL), original = try Data(contentsOf: drawingURL)
        #expect(SHA256.hash(data: png).map { String(format: "%02x", $0) }.joined() == "b230e42019b40ffab7c458df722d7f01dc16da14ff8fd17afc84264ef83525bb")
        #expect(try MobileSketchPNG.drawingData(in: png) == original)
        let decoded = try #require(try MobileSketchPNG.drawing(in: png))
        #expect(decoded == (try PKDrawing(data: original)))
        #expect(decoded.strokes.count == 1)
        let raster = try #require(decoded.image(from: rect, scale: 1).cgImage)
        let bytes = try pixels(raster)
        #expect(stride(from: 3, to: bytes.count, by: 4).contains { bytes[$0] != 0 })
        #expect(try decodedImage(png).width == 96)
    }

