    @Test func ordinaryPNGStaysOrdinaryAndReplacementKeepsOtherChunksExactly() throws {
        let png = try regularPNG()
        #expect(try MobileSketchPNG.drawingData(in: png) == nil)
        #expect(try MobileSketchPNG.drawing(in: png) == nil)
        var parts = chunks(png)
        parts.insert(("zzZZ", Data([1, 2, 3])), at: parts.count - 1)
        let source = rebuild(parts)
        let one = try MobileSketchPNG.embed(drawing: Self.fixtureDrawing(), in: source)
        let replacement = Self.fixtureDrawing(offset: 2)
        let two = try MobileSketchPNG.embed(drawing: replacement, in: one)
        #expect(try MobileSketchPNG.drawing(in: two) == replacement)
        #expect(chunks(two).filter { $0.type == "thND" }.count == 1)
        #expect(rebuild(chunks(two).filter { $0.type != "thND" }) == source)
        let empty = try MobileSketchPNG.embed(drawing: PKDrawing(), in: png)
        #expect(try MobileSketchPNG.drawing(in: empty)?.strokes.isEmpty == true)
    }

    @Test func embeddingAtChunkLimitRejectsGrowthButAllowsDrawingReplacement() throws {
        let limit = 16_384
        func padded(_ png: Data) -> Data {
            var parts = chunks(png)
            parts.insert(contentsOf: Array(repeating: (type: "zzZZ", data: Data()), count: limit - parts.count),
                         at: parts.count - 1)
            return rebuild(parts)
        }
        let ordinary = padded(try regularPNG())
        #expect(chunks(ordinary).count == limit)
        #expect(try MobileSketchPNG.drawingData(in: ordinary) == nil)
        #expect(throws: MobileSketchPNG.Failure.tooLarge) {
            try MobileSketchPNG.embed(drawing: Self.fixtureDrawing(), in: ordinary)
        }
        let original = Self.fixtureDrawing()
        let embedded = padded(try MobileSketchPNG.embed(drawing: original, in: regularPNG()))
        #expect(chunks(embedded).count == limit)
        #expect(try MobileSketchPNG.drawing(in: embedded) == original)
        let replacement = Self.fixtureDrawing(offset: 2)
        let replaced = try MobileSketchPNG.embed(drawing: replacement, in: embedded)
        #expect(chunks(replaced).count == limit)
        #expect(try MobileSketchPNG.drawing(in: replaced) == replacement)
        #expect(rebuild(chunks(replaced).filter { $0.type != "thND" }) ==
                rebuild(chunks(embedded).filter { $0.type != "thND" }))
    }

    @Test func malformedFramingCRCAndTrailingBytesNeverBecomeOrdinaryImages() throws {
        let png = try regularPNG()
        var badSignature = png; badSignature[0] ^= 1
        var badCRC = png; badCRC[29] ^= 1
        var hugeLength = png; hugeLength.replaceSubrange(8..<12, with: [255, 255, 255, 255])
        let malformed = [badSignature, badCRC, hugeLength, Data(png.prefix(7)), Data(png.dropLast()), png + Data([0])]
        for bytes in malformed { #expect(throws: (any Error).self) { try MobileSketchPNG.drawingData(in: bytes) } }
    }

    @Test func duplicateDrawingInvalidVersionInvalidArchiveAndOversizeAreRefused() throws {
        let png = try MobileSketchPNG.embed(drawing: Self.fixtureDrawing(), in: regularPNG())
        let all = chunks(png), drawingChunk = try #require(all.first { $0.type == "thND" })
        var duplicate = all; duplicate.insert(drawingChunk, at: duplicate.count - 1)
        #expect(throws: (any Error).self) { try MobileSketchPNG.drawingData(in: rebuild(duplicate)) }
        for payload in [Data([84, 78, 80, 75, 2, 1]), Data([84, 78, 80, 75, 1, 0]), Data([0])] {
            let altered = rebuild(all.map { $0.type == "thND" ? ("thND", payload) : $0 })
            #expect(throws: (any Error).self) { try MobileSketchPNG.drawingData(in: altered) }
            #expect(throws: (any Error).self) { try MobileSketchPNG.embed(drawing: Self.fixtureDrawing(), in: altered) }
        }
        #expect(throws: (any Error).self) {
            try MobileSketchPNG.embed(drawingData: Data(count: MobileSketchPNG.maximumDrawingBytes + 1), in: regularPNG())
        }
        let oversizedPayload = Data([84, 78, 80, 75, 1]) + Data(count: MobileSketchPNG.maximumDrawingBytes + 1)
        let oversizedPNG = rebuild(all.map { $0.type == "thND" ? ("thND", oversizedPayload) : $0 })
        #expect(throws: (any Error).self) { try MobileSketchPNG.drawingData(in: oversizedPNG) }
    }

    @Test func criticalOrderingReservedBitAndImageBoundsAreChecked() throws {
        let original = chunks(try regularPNG())
        var unknownCritical = original; unknownCritical.insert(("ABCD", Data()), at: 1)
        var badReserved = original; badReserved.insert(("zzzz", Data()), at: 1)
        var duplicateHeader = original; duplicateHeader.insert(original[0], at: 1)
        var noData = original.filter { $0.type != "IDAT" }
        var invalidEnd = original; invalidEnd[invalidEnd.count - 1] = ("IEND", Data([0]))
        var hugeImage = original; hugeImage[0].data.replaceSubrange(0..<4, with: [127, 255, 255, 255])
        var zeroImage = original; zeroImage[0].data.replaceSubrange(0..<4, with: [0, 0, 0, 0])
        noData.insert(("IDAT", Data([1, 2, 3])), at: noData.count - 1) // Correct CRC, invalid zlib/image stream.
        for parts in [unknownCritical, badReserved, duplicateHeader, invalidEnd, hugeImage, zeroImage, noData] {
            #expect(throws: (any Error).self) { try MobileSketchPNG.drawingData(in: rebuild(parts)) }
        }
        let idat = try #require(original.firstIndex { $0.type == "IDAT" })
        var split = original
        let payload = split[idat].data
        split.replaceSubrange(idat...idat, with: [("IDAT", Data(payload.prefix(1))), ("zzZZ", Data()), ("IDAT", Data(payload.dropFirst()))])
        #expect(throws: (any Error).self) { try MobileSketchPNG.drawingData(in: rebuild(split)) }
    }

    @Test func invalidZlibAdlerTrailingBytesAndWrongScanlineDataAreRejectedEvenWithValidChunkCRC() throws {
        let ihdr = Data([0, 0, 0, 1, 0, 0, 0, 1, 8, 6, 0, 0, 0]) // 1x1 RGBA8
        let validStream = storedZlib([0, 255, 0, 0, 255])
        let valid = rebuild([("IHDR", ihdr), ("IDAT", validStream), ("IEND", Data())])
        #expect(try MobileSketchPNG.drawingData(in: valid) == nil)
        var badAdler = validStream; badAdler[badAdler.count - 1] ^= 1
        let badStreams = [Data([1, 2, 3]), badAdler, validStream + Data([0]),
                          storedZlib([5, 255, 0, 0, 255]), storedZlib([0, 255, 0, 0]),
                          storedZlib([0, 255, 0, 0, 255, 0])]
        for stream in badStreams {
            let malformed = rebuild([("IHDR", ihdr), ("IDAT", stream), ("IEND", Data())])
            #expect(throws: (any Error).self) { try MobileSketchPNG.drawingData(in: malformed) }
        }
        // Consecutive IDAT chunks form ONE zlib stream, even when splitting its header/checksum.
        let split = rebuild([("IHDR", ihdr)] + validStream.map { ("IDAT", Data([$0])) } + [("IEND", Data())])
        #expect(try MobileSketchPNG.drawingData(in: split) == nil)
        var adam7 = ihdr; adam7[12] = 1
        #expect(try MobileSketchPNG.drawingData(in: rebuild([("IHDR", adam7), ("IDAT", validStream), ("IEND", Data())])) == nil)
    }

    @Test func compressedMetadataStaysOrdinaryButCannotEnterSketchOrPencilKitDecode() throws {
        let base = chunks(try regularPNG())
        let expanded = Data(repeating: 65, count: 2 * 1024 * 1024)
        let compressed = try compressedZlib(expanded)
        #expect(compressed.count < expanded.count / 100)
        let metadata: [(type: String, data: Data)] = [
            ("zTXt", Data("Comment\0".utf8) + Data([0]) + compressed),
            // Compression flag is AFTER the keyword NUL, not at a fixed chunk offset.
            ("iTXt", Data("Longer keyword\0".utf8) + Data([1, 0, 0, 0]) + compressed),
            ("iCCP", Data("Profile\0".utf8) + Data([0]) + compressed),
        ]
        for metadataChunk in metadata {
            var parts = base; parts.insert(metadataChunk, at: 1)
            let original = rebuild(parts)
            #expect(try MobileSketchPNG.rasterPNGForValidation(in: original) == rebuild(base.filter { ["IHDR", "PLTE", "IDAT", "IEND"].contains($0.type) }))
            #expect(try MobileSketchPNG.drawingData(in: original) == nil)
            #expect(throws: MobileSketchPNG.Failure.unsupportedMetadata) {
                try MobileSketchPNG.embed(drawing: Self.fixtureDrawing(), in: original)
            }
            // An invalid archive demonstrates that the metadata gate precedes PencilKit decode.
            parts.insert(("thND", Data([84, 78, 80, 75, 1, 0])), at: parts.count - 1)
            #expect(throws: MobileSketchPNG.Failure.unsupportedMetadata) {
                try MobileSketchPNG.drawingData(in: rebuild(parts))
            }
            #expect(throws: MobileSketchPNG.Failure.unsupportedMetadata) {
                try MobileSketchPNG.embed(drawingData: Data([0]), in: original)
            }
            var corrupt = original
            let chunkStart = 8 + base[0].data.count + 12
            corrupt[chunkStart + 8] ^= 1
            #expect(throws: MobileSketchPNG.Failure.invalidCRC) { try MobileSketchPNG.drawingData(in: corrupt) }
            var malformed = original
            malformed.replaceSubrange(chunkStart..<(chunkStart + 4), with: [255, 255, 255, 255])
            #expect(throws: MobileSketchPNG.Failure.invalidPNG) { try MobileSketchPNG.drawingData(in: malformed) }
        }
    }

    @Test func benignCompressedTextAndActualICCProfileRemainOrdinaryButSketchGateRefusesThem() throws {
        let base = chunks(try regularPNG()).filter { !["sRGB", "iCCP", "gAMA", "cHRM"].contains($0.type) }
        let profile = try #require(CGColorSpace(name: CGColorSpace.sRGB)?.copyICCData()) as Data
        let metadata: [(type: String, data: Data)] = [
            ("iCCP", Data("sRGB profile\0".utf8) + Data([0]) + (try compressedZlib(profile))),
            ("zTXt", Data("Comment\0".utf8) + Data([0]) + (try compressedZlib(Data("Benign text".utf8)))),
            ("iTXt", Data("Description\0".utf8) + Data([1, 0, 0, 0]) + (try compressedZlib(Data("Compressed UTF-8 🐻".utf8)))),
        ]
        for metadataChunk in metadata {
            var parts = base; parts.insert(metadataChunk, at: 1)
            let original = rebuild(parts)
            #expect(try MobileSketchPNG.drawingData(in: original) == nil)
            #expect(try decodedImage(original).width == 96) // Benign original is independently decodable.
            #expect(throws: MobileSketchPNG.Failure.unsupportedMetadata) {
                try MobileSketchPNG.embed(drawing: Self.fixtureDrawing(), in: original)
            }
        }
    }

    @Test func uncompressedInternationalAndPlainTextMetadataArePreservedExactly() throws {
        let base = chunks(try regularPNG())
        let plainText = Data("Comment\0ordinary text".utf8)
        let international = Data("Title\0".utf8) + Data([0, 0]) + Data("de\0Überschrift\0Inhalt 🐻".utf8)
        var parts = base
        parts.insert(contentsOf: [("tEXt", plainText), ("iTXt", international), ("zzZZ", Data([0, 1, 255]))], at: 1)
        let original = rebuild(parts), drawing = Self.fixtureDrawing()
        #expect(try MobileSketchPNG.drawingData(in: original) == nil)
        let embedded = try MobileSketchPNG.embed(drawing: drawing, in: original)
        #expect(try MobileSketchPNG.drawing(in: embedded) == drawing)
        #expect(try MobileSketchPNG.rasterPNGForValidation(in: embedded) == rebuild(base.filter { ["IHDR", "PLTE", "IDAT", "IEND"].contains($0.type) }))
        #expect(rebuild(chunks(embedded).filter { $0.type != "thND" }) == original)
    }

    @Test func malformedInternationalMetadataIsRefusedOnlyAtSketchGate() throws {
        let base = chunks(try regularPNG())
        let keyword = Data("Title\0".utf8)
        var missingMethod: Data = keyword
        missingMethod.append(contentsOf: [UInt8(0)])
        var invalidFlag: Data = keyword
        invalidFlag.append(contentsOf: [UInt8(2), 0, 0, 0])
        var missingTranslationTerminator: Data = keyword
        missingTranslationTerminator.append(contentsOf: [UInt8(0), 0])
        missingTranslationTerminator.append(Data("en\0missing translated terminator".utf8))
        var invalidUTF8: Data = keyword
        invalidUTF8.append(contentsOf: [UInt8(0), 0, 0, 0, 255])
        let malformed: [Data] = [Data(), Data("No separator".utf8), Data([UInt8(0), 0, 0, 0, 0]),
            missingMethod, invalidFlag, missingTranslationTerminator, invalidUTF8]
        for metadata in malformed {
            var parts = base; parts.insert(("iTXt", metadata), at: 1)
            let ordinary = rebuild(parts)
            #expect(try MobileSketchPNG.drawingData(in: ordinary) == nil)
            #expect(throws: MobileSketchPNG.Failure.invalidMetadata) {
                try MobileSketchPNG.embed(drawing: Self.fixtureDrawing(), in: ordinary)
            }
            parts.insert(("thND", Data([84, 78, 80, 75, 1, 0])), at: parts.count - 1)
            #expect(throws: MobileSketchPNG.Failure.invalidMetadata) {
                try MobileSketchPNG.drawingData(in: rebuild(parts))
            }
        }
    }

    @Test func validPaletteAlphaSixteenBitAndMultiPassAdam7SurviveRasterOnlyValidation() throws {
        func header(width: UInt8, height: UInt8, depth: UInt8, color: UInt8, interlace: UInt8 = 0) -> Data {
            Data([0, 0, 0, width, 0, 0, 0, height, depth, color, 0, 0, interlace])
        }
        let palette = rebuild([("IHDR", header(width: 1, height: 1, depth: 1, color: 3)),
            ("PLTE", Data([255, 0, 0, 0, 255, 0])), ("tRNS", Data([0, 255])),
            ("IDAT", storedZlib([0, 0])), ("IEND", Data())])
        let alpha16 = rebuild([("IHDR", header(width: 1, height: 1, depth: 16, color: 6)),
            ("IDAT", storedZlib([0, 255, 255, 0, 0, 0, 0, 128, 128])), ("IEND", Data())])
        // Independent explicit 8x8 RGBA8 Adam7 pass sizes: (1x1),(1x1),(2x1),
        // (2x2),(4x2),(4x4),(8x4). All seven passes have real scanlines.
        var interlacedRows: [UInt8] = []
        for (columns, rows) in [(1, 1), (1, 1), (2, 1), (2, 2), (4, 2), (4, 4), (8, 4)] {
            for _ in 0..<rows { interlacedRows += [0] + Array(repeating: [UInt8(255), 0, 0, 255], count: columns).flatMap { $0 } }
        }
        #expect(interlacedRows.count == 271)
        let adam7 = rebuild([("IHDR", header(width: 8, height: 8, depth: 8, color: 6, interlace: 1)),
            ("IDAT", storedZlib(interlacedRows)), ("IEND", Data())])
        let drawing = Self.fixtureDrawing()
        for png in [palette, alpha16, adam7] {
            #expect(try MobileSketchPNG.drawingData(in: png) == nil)
            #expect(try MobileSketchPNG.drawing(in: MobileSketchPNG.embed(drawing: drawing, in: png)) == drawing)
        }
        let paletteRaster = try MobileSketchPNG.rasterPNGForValidation(in: palette)
        #expect(chunks(paletteRaster).map { $0.type } == ["IHDR", "PLTE", "IDAT", "IEND"])
        // Stripping tRNS is only for decoder validation: the transport output retains transparency.
        let paletteSketch = try MobileSketchPNG.embed(drawing: Self.fixtureDrawing(), in: palette)
        #expect(try pixels(decodedImage(paletteSketch)) == pixels(decodedImage(palette)))
        #expect(try pixels(decodedImage(alpha16)) == pixels(decodedImage(MobileSketchPNG.rasterPNGForValidation(in: alpha16))))
        #expect(try pixels(decodedImage(adam7)) == Data(Array(repeating: [UInt8(255), 0, 0, 255], count: 64).flatMap { $0 }))
    }

    @Test(arguments: ["acTL", "fcTL", "fdAT"])
    func animationChunksAreExplicitlyUnsupportedBeforeNativeDecode(type: String) throws {
        var parts = chunks(try regularPNG())
        parts.insert((type, Data()), at: 1)
        #expect(throws: MobileSketchPNG.Failure.unsupportedAnimation) {
            try MobileSketchPNG.rasterPNGForValidation(in: rebuild(parts))
        }
        #expect(throws: MobileSketchPNG.Failure.unsupportedAnimation) {
            try MobileSketchPNG.drawingData(in: rebuild(parts))
        }
    }

    private func compressedZlib(_ input: Data) throws -> Data {
        var size = compressBound(uLong(input.count))
        var output = Data(count: Int(size))
        let status = output.withUnsafeMutableBytes { destination in
            input.withUnsafeBytes { source in
                compress2(destination.bindMemory(to: UInt8.self).baseAddress, &size,
                    source.bindMemory(to: UInt8.self).baseAddress, uLong(input.count), Z_BEST_COMPRESSION)
            }
        }
        try #require(status == Z_OK)
        output.count = Int(size)
        return output
    }

    /// Tiny uncompressed zlib stream, independent of the production inflater.
    private func storedZlib(_ bytes: [UInt8]) -> Data {
        let length = UInt16(bytes.count), inverse = ~length
        var result = Data([0x78, 0x01, 0x01, UInt8(truncatingIfNeeded: length), UInt8(length >> 8),
                           UInt8(truncatingIfNeeded: inverse), UInt8(inverse >> 8)])
        result.append(contentsOf: bytes)
        var a: UInt32 = 1, b: UInt32 = 0
        for byte in bytes { a = (a + UInt32(byte)) % 65521; b = (b + a) % 65521 }
        let adler = b << 16 | a
        result.append(contentsOf: [24, 16, 8, 0].map { UInt8(truncatingIfNeeded: adler >> $0) })
        return result
    }

    // Mutation helpers are intentionally independent of the production parser and table-based CRC.
    private func chunks(_ data: Data) -> [(type: String, data: Data)] {
        let bytes = [UInt8](data)
        var position = 8, result: [(String, Data)] = []
        while position + 12 <= bytes.count {
            let size = bytes[position..<position + 4].reduce(0) { ($0 << 8) | Int($1) }
            guard size <= bytes.count - position - 12 else { break }
            result.append((String(bytes: bytes[position + 4..<position + 8], encoding: .ascii)!, Data(bytes[position + 8..<position + 8 + size])))
            position += 12 + size
        }
        return result
    }
    private func rebuild(_ parts: [(type: String, data: Data)]) -> Data {
        var output = Data([137, 80, 78, 71, 13, 10, 26, 10])
        for part in parts {
            let typeAndData = Data(part.type.utf8) + part.data
            var crc: UInt32 = .max
            for byte in typeAndData {
                crc ^= UInt32(byte)
                for _ in 0..<8 { crc = (crc >> 1) ^ ((crc & 1) == 1 ? 0xedb88320 : 0) }
            }
            for value in [UInt32(part.data.count)] { output.append(contentsOf: [24, 16, 8, 0].map { UInt8(truncatingIfNeeded: value >> $0) }) }
            output.append(typeAndData)
            output.append(contentsOf: [24, 16, 8, 0].map { UInt8(truncatingIfNeeded: (~crc) >> $0) })
        }
        return output
    }
}
